def check_json() -> None:
    data = json.loads(_read(MAP_JSON))
    _require(data.get("schema") == "engel_core_continuity_map_v1", "continuity JSON schema mismatch")
    _require(data.get("continuity_status") == "READ_ONLY_INDEX", "continuity status mismatch")
    _require(data.get("trusted_memory_write_status") == "BLOCKED / NOT_PERFORMED", "trusted memory status mismatch")
    _require(data.get("research_intake_status") == "READ_ONLY_INTAKE / NOT_TRUSTED_MEMORY", "research intake status mismatch")
    _require(data.get("research_intake_trusted_memory_write_status") == "BLOCKED / NOT_PERFORMED", "research intake trusted memory status mismatch")
    _require(data.get("research_intake_contract_status") == "PRESENT", "research intake contract status mismatch")
    _require(data.get("research_learning_status") == "CANDIDATES_AND_REVIEWS_ONLY", "research learning status mismatch")
    _require(data.get("research_trusted_memory_status") == "BLOCKED / NOT_PERFORMED", "research trusted memory status mismatch")
    _require(data.get("memory_candidate_workflow_status") == "PROPOSAL_ONLY / NOT_TRUSTED_MEMORY", "memory candidate workflow status mismatch")
    _require(data.get("memory_candidate_trusted_memory_status") == "BLOCKED / NOT_PERFORMED", "memory candidate trusted memory status mismatch")
    _require(data.get("trusted_memory_candidate_boundary") == "Trusted Memory Candidate ≠ Trusted Memory", "memory candidate boundary mismatch")
    _require(data.get("memory_candidate_proposals_root") == "reports/memory_candidate_proposals", "memory candidate proposal root mismatch")
    _require(data.get("memory_candidate_contract_path") == "memory/ENGEL_MEMORY_CANDIDATE_WORKFLOW_CONTRACT_V1.md", "memory candidate contract path mismatch")
    _require(data.get("memory_candidate_report_path") == "reports/codex_bridge/ENGEL_TRUSTED_MEMORY_CANDIDATE_WORKFLOW.md", "memory candidate report path mismatch")
    _require(data.get("memory_candidate_workflow_contract_status") == "PRESENT", "memory candidate contract status mismatch")
    _require(data.get("code_companion_improvement_loop_status") == "FULL_LOOP_LIVE / PRODUCT_ONLY / NOT_TRUSTED_MEMORY", "Code Companion improvement loop status mismatch")
    _require(data.get("code_companion_project_builder_status") == "PLAN_AND_BOUNDED_CREATE", "Code Companion Project Builder status mismatch")
    _require(data.get("code_companion_continue_product_status") == "PLAN_ONLY / NOT_APPLIED", "Code Companion Continue Product status mismatch")
    _require(data.get("code_companion_patch_proposal_status") == "PATCH_PROPOSAL_ONLY / NOT_APPLIED", "Code Companion patch proposal status mismatch")
    _require(data.get("code_companion_patch_apply_status") == "PRODUCT_ONLY / APPROVAL_GATED", "Code Companion patch apply status mismatch")
    _require(data.get("code_companion_patch_apply_token") == "APPROVE_PRODUCT_PATCH", "Code Companion patch apply token mismatch")
    _require(data.get("code_companion_health_delta_status") == "REPORT_ONLY / NOT_TRUSTED_MEMORY", "Code Companion health delta status mismatch")
    _require(data.get("code_companion_lesson_suggestion_status") == "PROPOSAL_ONLY / NO_AUTO_LESSON", "Code Companion lesson suggestion status mismatch")
    _require(data.get("code_companion_lesson_candidate_bridge_status") == "APPROVE_LESSON_CANDIDATE / PENDING_REVIEW_ONLY", "Code Companion lesson candidate bridge status mismatch")
    _require(data.get("code_companion_lesson_review_status") == "READY_FOR_JOSH_REVIEW / NOT_TRUSTED_MEMORY", "Code Companion lesson review status mismatch")
    _require(data.get("code_companion_memory_handoff_status") == "MEMORY_CANDIDATE_PROPOSAL / NOT_TRUSTED_MEMORY", "Code Companion memory handoff status mismatch")
    _require(data.get("code_companion_memory_handoff_token") == "APPROVE_MEMORY_CANDIDATE_PROPOSAL", "Code Companion memory handoff token mismatch")
    _require(data.get("code_companion_trusted_memory_status") == "BLOCKED / NOT_PERFORMED", "Code Companion trusted memory status mismatch")
