    for key, values in paths.items():
        _require(isinstance(values, list), "paths entry is not list: " + str(key))
        for value in values:
            _require(isinstance(value, str), "path value is not string")
            candidate = Path(value)
            _require(not candidate.is_absolute(), "JSON path must be relative: " + value)
            _require(".." not in candidate.parts, "JSON path must not traverse: " + value)
            resolved = ROOT / candidate
            _require(_is_relative_to(resolved, ROOT), "JSON path escaped APP_ROOT: " + value)
            _require(not any(part in {"backups", "build_output", "build_work", "dist", "live"} for part in candidate.parts), "JSON path included skipped generated folder: " + value)

    flow = data.get("browser_queen_flow", [])
    _require(isinstance(flow, list), "browser queen flow missing")
    flow_text = " ".join(str(item) for item in flow)
    for needle in [
        "Browser Queen visible page interaction",
        "Untrusted Content Guard",
        "Research Intake",
        "Research Office / Overnight Research summary",
        "Josh/Guardian review",
        "trusted-memory workflow only if approved",
    ]:
        _require(needle in flow_text, "browser queen flow missing: " + needle)


