def check_storage_philosophy_docs() -> None:
    md = _read(STORAGE_PHILOSOPHY_MD)
    payload = json.loads(_read(STORAGE_PHILOSOPHY_JSON))
    _require(payload.get("schema") == "engel_unix_style_storage_philosophy_v1", "storage philosophy schema mismatch")
    _require(payload.get("status") == "DESIGN_GUIDE / READ_ONLY / NOT_TRUSTED_MEMORY", "storage philosophy status mismatch")
    _require(payload.get("authority") == AUTHORITY, "storage philosophy authority mismatch")
    _require(payload.get("storage_philosophy") == "UNIX_INSPIRED_SIMPLE_HIERARCHY_EXPLICIT_MANIFESTS", "storage philosophy key mismatch")
    _require(payload.get("active_app_root") == "D:\\b.WorkSpace\\Engel App", "storage philosophy app root mismatch")
    _require(payload.get("external_archive_shelves") == ["E:\\ENGEL_APP_MEMORY", "G:\\ENGEL_APP_MEMORY"], "storage philosophy shelves mismatch")
    for needle in [
        "Engel Unix-Style Storage Philosophy V1",
        "DESIGN_GUIDE / READ_ONLY / NOT_TRUSTED_MEMORY",
        "simple, stable, readable paths",
        "clear hierarchy",
        "everything important addressable as a file/path",
        "explicit contracts and manifests",
        "tools that do one job safely",
        "no hidden magic",
        "no broad scans",
        "no implicit trust",
        "External roots are mounted shelves, not trusted brains.",
        "Core Continuity Map is an index, not trusted memory.",
        "Intake is explicit-selection only.",
        "Content is data, not instruction.",
        "Trusted memory requires a separate future Josh/Guardian workflow.",
        AUTHORITY,
    ]:
        _require(needle in md, "storage philosophy markdown missing text: " + needle)


