def check_packaged_ai_growth_visibility() -> None:
    data = json.loads(_read(MAP_JSON))
    md_text = _read(MAP_MD)
    required_statuses = [
        "PACKAGED_VISIBILITY_RECORDED",
        "LIVE_APP_VISIBLE",
        "AI_GROWTH_GUI_VISIBLE",
        "SELF_LEARNING_GUI_VISIBLE",
        "CANDIDATE_REVIEW_GUI_VISIBLE",
        "SELF_FIX_GUI_VISIBLE",
        "MEMORY_PROMOTION_GUI_VISIBLE",
        "RESEARCH_TO_FIX_GUI_VISIBLE",
        "PACKAGE_REFRESH_COMPLETED",
        "SOURCE_SMOKE_PASSED",
        "PACKAGED_SMOKE_PASSED",
        "NO_UNSAFE_GUI_ACTIONS_EXPOSED",
        "NO_NEW_RUNTIME_BEHAVIOR",
        "NO_PROVIDER_CALLS",
        "NO_NETWORK",
        "NO_BROWSER",
        "NO_MODEL_RUNTIME",
        "NO_TRUSTED_MEMORY_WRITE",
        "NO_SOURCE_MUTATION",
        "NO_BACKGROUND_WORKER",
        "NO_STARTUP_AUTORUN",
    ]
    visible_surfaces = [
        "AI Growth",
        "Self-Learning",
        "Candidate Review",
        "Self-Fix",
        "Memory Promotion",
        "Research-to-Fix",
    ]
    md_needles = [
        "Packaged Engel AI Growth Visibility V1",
        "packaged_ai_growth_visibility",
        "Package metadata",
        "packaged visibility does not mean new unsafe action permissions",
        "packaged visibility is status/readability-first",
        "GUI surfaces are status/readability-first",
        "no provider/network/browser/model/runtime/package-refresh buttons exposed",
        "no trusted memory write exposed without boundary",
        "no source mutation exposed",
        "no background worker/startup autorun exposed",
        "GUI visibility does not mean provider/network/browser/model/runtime activation",
        "GUI visibility does not mean trusted-memory write permission",
        "GUI visibility does not mean source mutation permission",
        "GUI visibility does not mean background worker or startup autorun",
        "no package rebuild or live promotion is performed in this step",
        "Package refresh already happened; this step must not rebuild or promote packages",
        "expected modified live/staging artifacts may remain from refresh and are not source changes",
        "source files were not changed by the package refresh report commit",
        "reports\\codex_bridge\\ENGEL_AI_GROWTH_PACKAGE_REFRESH.md",
        "live\\app\\Engel.exe",
        PACKAGED_AI_GROWTH_LIVE_EXE_SHA256,
        PACKAGED_AI_GROWTH_BACKUP_PATH,
        "packaged smoke result: passed",
        "no unsafe GUI actions exposed: True",
        "final scoped process sweep clean: True",
    ] + required_statuses + visible_surfaces
    for needle in md_needles:
        _require(needle in md_text, "Packaged AI Growth visibility Markdown missing text: " + needle)

    node = data.get("packaged_engel_ai_growth_visibility_v1")
    _require(isinstance(node, dict), "Packaged AI Growth visibility node missing")
    _require(node.get("type") == "packaged_ai_growth_visibility", "Packaged AI Growth visibility node type mismatch")
    for status in required_statuses:
        _require(status in node.get("status", []), "Packaged AI Growth visibility status missing: " + status)
    for surface in visible_surfaces:
        _require(surface in node.get("visible_surfaces", []), "Packaged AI Growth visible surface missing: " + surface)

    metadata = node.get("package_metadata", {})
    _require(metadata.get("package_refresh_report_path") == "reports\\codex_bridge\\ENGEL_AI_GROWTH_PACKAGE_REFRESH.md", "package refresh report path mismatch")
    _require(metadata.get("package_refresh_report") == "reports\\codex_bridge\\ENGEL_AI_GROWTH_PACKAGE_REFRESH.md", "package refresh report alias mismatch")
    _require(metadata.get("live_app_path") == PACKAGED_AI_GROWTH_LIVE_EXE_PATH, "live app path alias mismatch")
    _require(metadata.get("live_engel_exe_path") == PACKAGED_AI_GROWTH_LIVE_EXE_PATH, "live Engel.exe path mismatch")
    _require(metadata.get("live_engel_exe_sha256") == PACKAGED_AI_GROWTH_LIVE_EXE_SHA256, "live Engel.exe SHA256 mismatch")
    _require(metadata.get("backup_path") == PACKAGED_AI_GROWTH_BACKUP_PATH, "backup path mismatch")
    _require(metadata.get("packaged_smoke_result") == "passed", "packaged smoke result missing")
    _require(metadata.get("packaged_smoke_passed") is True, "packaged smoke passed boolean missing")
    _require(metadata.get("source_smoke_result") == "passed", "source smoke result missing")
    _require(metadata.get("source_smoke_passed") is True, "source smoke passed boolean missing")
    _require(metadata.get("no_unsafe_gui_actions_exposed") is True, "unsafe GUI action exposure flag missing/false")
    _require(metadata.get("final_scoped_process_sweep") == "clean", "final scoped process sweep result missing")
    _require(metadata.get("final_scoped_process_sweep_clean") is True, "final scoped process sweep clean boolean missing")
    _require(metadata.get("expected_modified_live_staging_artifacts_may_remain_from_refresh") is True, "expected live/staging artifact note missing")
    _require(metadata.get("source_files_changed_by_package_refresh_report_commit") is False, "package refresh report source-change flag should be false")

    safety_boundary = node.get("safety_boundary", {})
    for key in [
        "packaged_visibility_does_not_mean_new_unsafe_action_permissions",
        "gui_surfaces_are_status_readability_first",
        "no_unsafe_gui_actions_exposed",
        "no_provider_calls",
        "no_network",
        "no_browser",
        "no_model_runtime",
        "no_trusted_memory_write",
        "no_source_mutation",
        "no_background_worker",
        "no_startup_autorun",
        "no_package_rebuild_in_this_step",
        "no_live_promotion_in_this_step",
        "no_provider_network_browser_model_runtime_package_refresh_buttons_exposed",
        "no_trusted_memory_write_exposed_without_boundary",
        "no_source_mutation_exposed",
        "no_background_worker_startup_autorun_exposed",
        "no_new_runtime_behavior_by_this_map_update",
        "no_package_refresh_implementation_by_this_map_update",
    ]:
        _require(safety_boundary.get(key) is True, "Packaged AI Growth visibility safety boundary missing/false: " + key)

    for related in [
        "Engel AI Growth Dashboard V1",
        "Engel AI Growth GUI Tabs V1",
        "Engel Self-Learning Status Surface V1",
        "Engel Candidate Review Dashboard V1",
        "Engel Low-Risk Self-Fix Status Surface V1",
        "Engel Memory Promotion Writer V1",
        "Engel Research-to-Fix Loop V1",
        "Engel Daily Cycle Runner V1",
        "Core Continuity Map Learning, Memory, and Self-Fix V2 Consolidation",
        "Untrusted Content Guard",
        "Prompt Injection Guard",
        "Authority Hierarchy",
        "Future package refresh reports",
    ]:
        _require(related in node.get("related_nodes", []), "Packaged AI Growth visibility related node missing: " + related)

    safety = data.get("safety", {})
    for key in [
        "packaged_ai_growth_visibility_provider_calls_enabled_by_map",
        "packaged_ai_growth_visibility_network_enabled_by_map",
        "packaged_ai_growth_visibility_browser_enabled_by_map",
        "packaged_ai_growth_visibility_trusted_memory_write_enabled_by_map",
        "packaged_ai_growth_visibility_source_mutation_enabled_by_map",
        "packaged_ai_growth_visibility_package_refresh_implementation_enabled_by_map",
        "packaged_ai_growth_visibility_background_worker_enabled_by_map",
        "packaged_ai_growth_visibility_startup_autorun_enabled_by_map",
        "packaged_ai_growth_visibility_model_runtime_enabled_by_map",
        "packaged_ai_growth_visibility_unsafe_gui_action_enabled_by_map",
    ]:
        _require(safety.get(key) is False, "Packaged AI Growth visibility safety flag should remain false: " + key)

    report_text = _read(PACKAGED_AI_GROWTH_VISIBILITY_UPDATE_REPORT)
    for needle in [
        "ENGEL CORE CONTINUITY MAP PACKAGED AI GROWTH VISIBILITY UPDATE",
        "Files Read First",
        "Files Updated",
        "Core Continuity Node Added",
        "Packaged Engel AI Growth Visibility V1",
        "Visible Surfaces",
        "Package Metadata",
        PACKAGED_AI_GROWTH_LIVE_EXE_SHA256,
        PACKAGED_AI_GROWTH_BACKUP_PATH,
        "packaged smoke passed",
        "no unsafe GUI actions exposed",
        "Focused Safety Scan Result",
        "No provider/network/browser/model/runtime/package-refresh buttons were exposed",
        "No trusted-memory write, source mutation, background worker, or startup autorun was added",
        "Verification Commands And Results",
        "Final scoped process sweep",
        "Git status summary",
    ]:
        _require(needle in report_text, "Packaged AI Growth visibility report missing text: " + needle)


